package co.serviasigna.domain;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * Texto de la política de tratamiento de datos y ubicación con su versión (tabla POLITICA_DATOS, Ley 1581 de 2012).
 * <p>
 * EN: Text of the data and location processing policy with its version (POLITICA_DATOS table, Colombian Law 1581 of
 * 2012).
 */
@Entity
@Table(name = "POLITICA_DATOS")
public class DataPolicy {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El número de versión. EN: The version number. */
    @Column(name = "VERSION", nullable = false, length = 10) private String version;
    /** El texto completo. EN: The full text. */
    @Lob @Column(name = "TEXTO", nullable = false) private String text;
    /** La fecha desde la que rige. EN: The date it applies from. */
    @Column(name = "VIGENTE_DESDE", nullable = false) private LocalDateTime effectiveFrom = LocalDateTime.now();
    /** Si es la versión vigente. EN: Whether it is the current version. */
    @Column(name = "VIGENTE", nullable = false) private boolean current = true;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected DataPolicy() {}

    /**
     * Crea una versión vigente de la política.
     * <p>
     * EN: Creates a current version of the policy.
     *
     * @param version número de versión, por ejemplo "1.1" / version number, for example "1.1"
     * @param text texto completo / full text
     */
    public DataPolicy(String version, String text) { this.version = version; this.text = text; }

    /**
     * Retira la política: deja de estar vigente.
     * <p>
     * EN: Withdraws the policy: it is no longer current.
     */
    public void withdraw() { current = false; }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el número de versión.
     * <p>
     * EN: Returns the version number.
     *
     * @return el número de versión / the version number
     */
    public String getVersion() { return version; }

    /**
     * Devuelve el texto completo.
     * <p>
     * EN: Returns the full text.
     *
     * @return el texto completo / the full text
     */
    public String getText() { return text; }

    /**
     * Devuelve la fecha desde la que rige.
     * <p>
     * EN: Returns the date it applies from.
     *
     * @return la fecha desde la que rige / the date it applies from
     */
    public LocalDateTime getEffectiveFrom() { return effectiveFrom; }

    /**
     * Indica si es la versión vigente.
     * <p>
     * EN: Tells whether it is the current version.
     *
     * @return true si se cumple / true if it applies
     */
    public boolean isCurrent() { return current; }
}
